/**
 * Make sure an unpaid request has a Stripe payment intent and a recorded
 * amount. Returns true when an intent exists (already or newly created),
 * false when there is nothing to charge (no credential type, or price 0).
 * Shared by REJECT_EXEMPTION, PAYMENT_REQUIRED and the admin resend action.
 */
async function ensurePaymentIntent(
  tx: TransactionClient,
  params: {
    request: typeof fobRequests.$inferSelect;
    tenantId: string;
  }
): Promise<boolean> {
  const { request, tenantId } = params;
  if (request.stripePaymentIntentId) return true;

  let amountCents = request.paymentAmountCents ?? 0;
  if (amountCents <= 0 && request.credentialTypeId) {
    const [credType] = await tx
      .select({ priceCents: credentialTypes.priceCents })
      .from(credentialTypes)
      .where(
        and(
          eq(credentialTypes.id, request.credentialTypeId),
          eq(credentialTypes.tenantId, tenantId)
        )
      )
      .limit(1);
    amountCents = credType?.priceCents ?? 0;
  }
  if (amountCents <= 0) return false;

  const [tenant] = await tx
    .select({ stripeAccountId: tenants.stripeAccountId })
    .from(tenants)
    .where(eq(tenants.id, tenantId))
    .limit(1);

  const intent = await createPaymentIntent({
    amountCents,
    stripeAccountId: tenant?.stripeAccountId ?? null,
    metadata: { requestId: request.id, tenantId },
  });

  await tx
    .update(fobRequests)
    .set({ stripePaymentIntentId: intent.paymentIntentId, paymentAmountCents: amountCents })
    .where(eq(fobRequests.id, request.id));

  return true;
}

/**
 * Admin "resend payment link": email the member the pay / cancel links for an
 * unpaid request without changing its status. Creates the Stripe intent if
 * the request never got one. Audited as an update with
 * metadata.action = payment_link_resent.
 */
export async function sendPaymentLinkEmail(
  tx: TransactionClient,
  params: { requestId: string; tenantId: string; actorId: string | null }
): Promise<{ sentTo: string }> {
  const [request] = await tx
    .select()
    .from(fobRequests)
    .where(and(eq(fobRequests.id, params.requestId), eq(fobRequests.tenantId, params.tenantId)))
    .limit(1);
  if (!request) throw new Error("Request not found");

  if (request.paidAt) {
    throw new Error("Cannot resend a payment link: this request has already been paid");
  }
  const resendable: string[] = [RequestStatus.SUBMITTED, RequestStatus.AWAITING_PAYMENT];
  if (!resendable.includes(request.status)) {
    throw new Error(
      `Cannot resend a payment link when status is "${request.status}". Must be awaiting payment.`
    );
  }
  if (request.paymentExempt) {
    throw new Error("Cannot resend a payment link: this request is payment exempt");
  }

  const ensured = await ensurePaymentIntent(tx, { request, tenantId: params.tenantId });
  if (!ensured) {
    throw new Error("Cannot resend a payment link: no price is configured for this request's credential type");
  }

  let recipientEmail: string | null = null;
  let memberName = "Member";
  if (request.requesterId) {
    const [user] = await tx
      .select({ email: users.email, firstName: users.firstName, lastName: users.lastName })
      .from(users)
      .where(eq(users.id, request.requesterId))
      .limit(1);
    if (user) {
      recipientEmail = user.email;
      memberName = `${user.firstName} ${user.lastName}`.trim() || "Member";
    }
  } else if (request.orphanEmail) {
    recipientEmail = request.orphanEmail;
    memberName = [request.orphanFirstName, request.orphanLastName].filter(Boolean).join(" ") || "Member";
  }
  if (!recipientEmail) {
    throw new Error("Cannot resend a payment link: no email address on this request");
  }

  const [tenant] = await tx
    .select({ name: tenants.name, slug: tenants.slug, settings: tenants.settings, logoUrl: tenants.logoUrl })
    .from(tenants)
    .where(eq(tenants.id, params.tenantId))
    .limit(1);
  if (!tenant) throw new Error("Organisation not found");

  const [fresh] = await tx
    .select({ paymentAmountCents: fobRequests.paymentAmountCents })
    .from(fobRequests)
    .where(eq(fobRequests.id, request.id))
    .limit(1);
  const amount = formatAmountCents(fresh?.paymentAmountCents ?? request.paymentAmountCents);
  const { paymentUrl, cancelUrl } = buildPaymentLinks({
    tenantSlug: tenant.slug,
    tenantId: params.tenantId,
    requestId: request.id,
  });

  await sendTemplatedEmail(
    recipientEmail,
    "paymentRequired",
    { memberName, amount, paymentUrl, cancelUrl },
    buildEmailConfig(tenant),
    undefined,
    {
      tx,
      tenantId: params.tenantId,
      entityType: AuditEntityType.FOB_REQUEST,
      entityId: request.id,
      actorId: params.actorId,
    }
  );

  await createAuditEntry(tx, {
    tenantId: params.tenantId,
    entityType: AuditEntityType.FOB_REQUEST,
    entityId: request.id,
    action: AuditAction.UPDATE,
    actorId: params.actorId,
    metadata: { action: "payment_link_resent", sentTo: recipientEmail },
  });

  return { sentTo: recipientEmail };
}

