export type PaymentIntentSnapshot = {
  status: Stripe.PaymentIntent.Status;
  amountCents: number;
};

/**
 * Read the live status of a payment intent. Used before any action that
 * assumes "unpaid" (require payment, resend link, abandoned sweep, cancel by
 * link): a late or failed webhook can leave paidAt null after the member has
 * in fact paid, and Stripe is the source of truth for that.
 */
export async function retrievePaymentIntent(params: {
  paymentIntentId: string;
  stripeAccountId: string | null;
}): Promise<PaymentIntentSnapshot> {
  const stripe = getStripe();
  const options: Stripe.RequestOptions = {};
  if (params.stripeAccountId) {
    options.stripeAccount = params.stripeAccountId;
  }
  const intent = await stripe.paymentIntents.retrieve(params.paymentIntentId, options);
  return { status: intent.status, amountCents: intent.amount };
}

/** True when money has been, or is being, taken on this intent. */
export function intentIsPaidOrProcessing(status: Stripe.PaymentIntent.Status): boolean {
  return status === "succeeded" || status === "processing";
}

