type EnsureIntentResult =
  | "ready" // a usable intent exists (already, or just created)
  | "paid" // Stripe shows the intent succeeded or processing: do not demand money
  | "no_price"; // nothing to charge (no credential type, or price 0)

/**
 * Make sure an unpaid request has a usable Stripe payment intent and a
 * recorded amount. Checks Stripe for an existing intent rather than trusting
 * paidAt (a late webhook leaves paidAt null after a real payment), and
 * replaces an intent that is cancelled (cancel then reopen) or whose amount
 * no longer matches the price. Shared by REJECT_EXEMPTION, PAYMENT_REQUIRED
 * and the admin resend action.
 */
async function ensurePaymentIntent(
  tx: TransactionClient,
  params: {
    request: typeof fobRequests.$inferSelect;
    tenantId: string;
  }
): Promise<EnsureIntentResult> {
  const { request, tenantId } = params;

  let amountCents = request.paymentAmountCents ?? 0;
  if (amountCents <= 0 && request.credentialTypeId) {
    const [credType] = await tx
      .select({ priceCents: credentialTypes.priceCents })
      .from(credentialTypes)
      .where(
        and(
          eq(credentialTypes.id, request.credentialTypeId),
          eq(credentialTypes.tenantId, tenantId)
        )
      )
      .limit(1);
    amountCents = credType?.priceCents ?? 0;
  }

  const [tenant] = await tx
    .select({ stripeAccountId: tenants.stripeAccountId })
    .from(tenants)
    .where(eq(tenants.id, tenantId))
    .limit(1);
  const stripeAccountId = tenant?.stripeAccountId ?? null;

  if (request.stripePaymentIntentId) {
    const existing = await retrievePaymentIntent({
      paymentIntentId: request.stripePaymentIntentId,
      stripeAccountId,
    });
    if (intentIsPaidOrProcessing(existing.status)) return "paid";
    const amountMatches = amountCents <= 0 || existing.amountCents === amountCents;
    if (existing.status !== "canceled" && amountMatches) return "ready";
    // Cancelled, or the price changed: fall through and create a fresh one.
  }

  if (amountCents <= 0) return "no_price";

  const intent = await createPaymentIntent({
    amountCents,
    stripeAccountId,
    metadata: { requestId: request.id, tenantId },
  });

  await tx
    .update(fobRequests)
    .set({ stripePaymentIntentId: intent.paymentIntentId, paymentAmountCents: amountCents })
    .where(eq(fobRequests.id, request.id));

  return "ready";
}

/**
 * Live Stripe check used by the public cancel-by-link route: refuse to cancel
 * when money has been, or is being, taken even if paidAt is still null.
 */
export async function requestHasPaymentInFlight(
  tx: TransactionClient,
  params: { request: typeof fobRequests.$inferSelect; tenantId: string }
): Promise<boolean> {
  if (params.request.paidAt) return true;
  if (!params.request.stripePaymentIntentId) return false;
  const [tenant] = await tx
    .select({ stripeAccountId: tenants.stripeAccountId })
    .from(tenants)
    .where(eq(tenants.id, params.tenantId))
    .limit(1);
  const existing = await retrievePaymentIntent({
    paymentIntentId: params.request.stripePaymentIntentId,
    stripeAccountId: tenant?.stripeAccountId ?? null,
  });
  return intentIsPaidOrProcessing(existing.status);
}

