export function paymentRequiredEmail(
  clubName: string,
  memberName: string,
  amount: string,
  paymentUrl: string,
  cancelUrl?: string,
  reason?: string,
  postIssue = false
): string {
  const reasonBlock = reason
    ? `<div style="margin: 0 0 16px; padding: 12px 16px; background-color: #fffbeb; border-left: 3px solid #f59e0b; border-radius: 4px;">
        <p style="margin: 0; color: #92400e; font-size: 13px;"><strong>Note from the club:</strong> ${reason}</p>
      </div>`
    : "";
  const lead = postIssue
    ? `A payment of <strong>${amount}</strong> is required for the ${credentialNoun()} you have already been issued.`
    : `A payment of <strong>${amount}</strong> is required before your request can proceed.`;
  const closing = postIssue
    ? `Your ${credentialNoun()} stays active. Once your payment is received we will confirm it by email. If you have already paid, please disregard this message.`
    : `Once your payment is received your request will move to review automatically. If you have already paid, please disregard this message.`;
  const body = `
    <h1 style="${heading()}">Payment Required</h1>
    <p style="${bodyText()}">
      Dear ${memberName.split(" ")[0]},
    </p>
    <p style="${bodyText()}">
      ${lead}
    </p>
    <div style="margin: 0 0 16px; padding: 12px 16px; background-color: #f0fdfa; border-left: 3px solid ${getPrimaryColour()}; border-radius: 4px;">
      <p style="margin: 0; color: #134e4a; font-size: 13px;"><strong>Amount due:</strong> ${amount}</p>
    </div>
    ${reasonBlock}
    ${paymentActions(paymentUrl, cancelUrl)}
    <p style="${mutedText()}">
      ${closing}
    </p>`;
  return layout(clubName, body);
}

